head.b:skin:
/* =========================================================
   NAVY PORTAL v4 - Blogger Template
   Page-by-page portal layout:
   1) Navy header (logo, menu, yellow button, search)
   2) "Selected Articles" featured block
   3) Label block: tab + big post + 3 rows with dividers
   4) Two label lists with stars + "See all" button
   5) "Latest Articles" 2-column cards with corner label
   6) Footer: logo, text, link columns, social icons, badges, DMCA line
   Edit colors in :root.

   SIDEBAR: off on home/label pages (full width), on for posts.
   To also show it on the home page, see the "SIDEBAR SWITCH"
   comment in the Responsive section.
   ========================================================= */
:root{
  --navy:#0f3870;
  --navy-dark:#0a2a55;
  --logo:#ffc61a;
  --accent:#ffc107;
  --red:#d9411e;
  --bg:#ffffff;
  --text:#2b3340;
  --head:#111111;
  --title:#2d3340;
  --link:#0b4f8a;
  --muted:#6b7785;
  --line:#dcdfe5;
  --soft:#f1f4f9;
  --font:'Roboto',system-ui,-apple-system,'Segoe UI',Arial,sans-serif;
}
:root[data-theme='dark']{
  --bg:#0d1a2e;
  --text:#dbe5f3;
  --head:#f4f7fc;
  --title:#eef3fb;
  --link:#8db8ff;
  --muted:#9fb0c7;
  --line:#22385a;
  --soft:#14274a;
}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--text);font-family:var(--font);font-size:16px;line-height:1.6}
a{color:var(--link);text-decoration:none}
a:hover{color:var(--red)}
img{max-width:100%;height:auto}
h1,h2,h3,h4{line-height:1.28;margin:0 0 .5em;color:var(--head)}
.wrap{max-width:984px;margin:0 auto;padding:0 16px}
.section,.widget{margin:0}
.brand .widget,.nav .widget{margin:0}
:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.sr{position:absolute;left:-9999px}
#progress{position:fixed;top:0;left:0;height:3px;width:0;background:var(--accent);z-index:100}

/* ---------- 1) Header ---------- */
.site-header{position:sticky;top:0;z-index:60;background:var(--navy);color:#fff}
.bar{display:flex;align-items:center;gap:18px;min-height:68px;flex-wrap:wrap}
.brand{flex:0 0 auto}
.logo{display:flex;align-items:center;gap:7px}
.logo svg{flex:0 0 auto}
.logo-text{font-size:30px;font-weight:900;letter-spacing:.4px;text-transform:uppercase;line-height:1;margin:0;color:#fff}
.logo-text a{color:#fff}
.go{color:var(--logo)}
.nav{flex:1;display:flex;justify-content:flex-end}
.menu ul{list-style:none;margin:0;padding:0;display:flex;align-items:center;gap:4px}
.menu li a{display:block;padding:8px 14px;color:#fff;font-size:16px;font-weight:500}
.menu li a:hover{color:var(--accent)}
.menu li:last-child a{background:var(--accent);color:#1b1b1b;border-radius:999px;padding:6px 16px;margin-left:10px}
.menu li:last-child a:hover{background:#fff;color:var(--navy)}
.ic-btn{background:transparent;border:0;color:#fff;cursor:pointer;padding:8px;display:flex;align-items:center}
.ic-btn:hover{color:var(--accent)}
.menu-btn{display:none;font-size:24px;line-height:1}
.search-pop{display:none;background:var(--navy-dark);padding:10px 0}
.search-open .search-pop{display:block}
.search-pop form{display:flex;background:#fff;border-radius:999px;overflow:hidden;max-width:560px;margin:0 auto}
.search-pop input{flex:1;border:0;padding:10px 18px;font:inherit;font-size:15px;outline:0;background:transparent;color:#1f2933;min-width:0}
.search-pop button{border:0;background:var(--accent);padding:0 20px;font-weight:700;cursor:pointer;color:#1b1b1b;font-family:inherit}
.ad{text-align:center;margin:12px 0}

/* ---------- Layout ---------- */
.layout{display:grid;grid-template-columns:minmax(0,1fr);gap:54px;padding-top:26px;padding-bottom:44px}
.sidebar{display:none}
.page-item .layout,.page-static_page .layout{grid-template-columns:minmax(0,1fr) 324px}
.page-item .sidebar,.page-static_page .sidebar{display:block}

/* Shared bits */
.sec-h{font-size:24px;font-weight:700;margin:0 0 18px;color:var(--head)}
.stars{font-size:17px;color:#555;margin-left:10px;letter-spacing:2px;font-weight:400}
[data-theme='dark'] .stars{color:#9fb0c7}
.sec-row{display:flex;justify-content:space-between;align-items:center;margin:0 0 20px}
.sec-row .sec-h{margin:0}
.btn-o{border:1px solid var(--navy);color:var(--link);font-size:13px;padding:5px 11px;border-radius:2px;background:transparent;white-space:nowrap;line-height:1.3}
.btn-o:hover{background:var(--navy);border-color:var(--navy);color:#fff}
.btn{display:inline-block;background:var(--navy);color:#fff;font-weight:700;font-size:14px;padding:10px 26px;border:0;cursor:pointer;font-family:inherit;border-radius:2px}
.btn:hover{background:var(--accent);color:#1b1b1b}
.tag{display:inline-block;background:var(--navy);color:#fff;font-size:12.5px;font-weight:500;text-transform:uppercase;padding:6px 13px;line-height:1.2;box-shadow:3px 3px 0 rgba(15,56,112,.18)}
a.tag:hover{background:var(--red);color:#fff}
.t1{color:var(--title);font-weight:700}
.t1 a{color:inherit}
.t1::first-letter{color:var(--red);font-size:1.3em;font-weight:900}
.t1 a:hover{color:var(--red)}
.meta2{font-size:13px;color:#444}
[data-theme='dark'] .meta2{color:var(--muted)}
.au{color:var(--link);text-decoration:underline}
.blk{padding-bottom:30px;border-bottom:1px solid var(--line);margin-bottom:30px}

/* ---------- 2) Selected Articles (featured) ---------- */
.feat{display:grid;grid-template-columns:minmax(0,1.23fr) minmax(0,1fr);gap:37px;align-items:center}
.feat-img{display:block;aspect-ratio:16/9;background:var(--soft);overflow:hidden}
.feat-img img{width:100%;height:100%;object-fit:cover;display:block}
.feat-body{display:flex;flex-direction:column;gap:14px;align-items:flex-start}
.feat-body h3{font-size:26px;line-height:1.3;margin:0}
.feat-body p{margin:0;font-size:15px;line-height:1.55;color:#3d4452;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
[data-theme='dark'] .feat-body p{color:var(--text)}

/* ---------- 3) Label block: tab + big + rows ---------- */
.tab-head{display:flex;align-items:center;margin:0 0 22px}
.tab-head:after{content:'';flex:1;height:2px;background:var(--line)}
.tab{background:var(--navy);color:#fff;font-size:15px;padding:7px 14px;box-shadow:3px 3px 0 rgba(15,56,112,.2)}
.tab:hover{background:var(--red);color:#fff}
.bl{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:56px;align-items:start}
.bl-img{display:block;aspect-ratio:16/9;background:var(--soft);overflow:hidden;margin-bottom:14px}
.bl-img img{width:100%;height:100%;object-fit:cover;display:block}
.bl h3{font-size:20px;margin:0}
.bl .rows .row{padding:14px 0;margin:0;border-top:1px solid var(--line)}
.bl .rows .row:first-child{border-top:0;padding-top:0}

/* Rows (thumb + title) */
.rows{list-style:none;margin:0;padding:0}
.row{display:flex;gap:22px;margin-bottom:26px;align-items:flex-start}
.row-img{flex:0 0 115px;height:80px;background:var(--soft);overflow:hidden;display:block}
.row-img img{width:100%;height:100%;object-fit:cover;display:block}
.row-t{font-size:17px;font-weight:700;line-height:1.3;color:var(--head)}
.row-t:hover{color:var(--red)}

/* ---------- 4) Two label lists ---------- */
.two-col{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:56px}
.lbl-head{display:flex;align-items:center;margin-bottom:24px}
.lbl-head h3{margin:0;font-size:24px;font-weight:500;color:var(--title)}
.lbl-head .btn-o{margin-left:auto}

/* ---------- 5) Latest Articles: 2-column cards ---------- */
.cards{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:44px 56px}
.pcard{min-width:0}
.pc-img{position:relative;aspect-ratio:16/9;background:var(--soft);overflow:hidden}
.pc-img>a{display:block;width:100%;height:100%}
.pc-img img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .4s}
.pcard:hover .pc-img img{transform:scale(1.03)}
.chip-w{position:absolute;top:0;left:0;background:var(--bg);color:#8a929e;font-size:14px;padding:7px 16px 7px 12px;line-height:1.2;z-index:2}
a.chip-w:hover{color:var(--red)}
.pc-img>a.chip-w{width:auto;height:auto}
.pcard h2{font-size:20px;margin:20px 0 8px}
.pcard .meta2{margin-bottom:10px}
.pcard p{margin:0;font-size:16px;line-height:1.45;color:#333b49;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
[data-theme='dark'] .pcard p{color:var(--text)}
.pager{display:flex;justify-content:center;gap:12px;margin:36px 0 0;flex-wrap:wrap}
.archive-title{font-size:26px;margin:0 0 22px;padding-left:12px;border-left:5px solid var(--accent)}

/* ---------- Single post ---------- */
.crumbs{font-size:13px;color:var(--muted);display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}
.crumbs .cur{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%}
.post-full h1.post-title{font-size:32px;margin-bottom:8px}
.post-body{font-size:17px;line-height:1.85;overflow-wrap:anywhere;margin-top:16px}
.post-body h2,.post-body h3{margin-top:1.6em;scroll-margin-top:90px}
.post-body img{border-radius:4px}
.post-body blockquote{margin:1.2em 0;padding:8px 18px;border-left:4px solid var(--accent);background:var(--soft)}
.post-body pre{background:var(--navy-dark);color:#e6eefb;padding:14px;overflow:auto;font-size:14px}
.post-body table{border-collapse:collapse;display:block;overflow-x:auto;max-width:100%}
.post-body td,.post-body th{border:1px solid var(--line);padding:8px 12px}
.toc{background:var(--soft);padding:12px 18px;margin:18px 0}
.toc summary{cursor:pointer;font-weight:700;color:var(--head)}
.toc ol{margin:8px 0 0;padding-left:20px;font-size:15px}
.toc li.sub{margin-left:16px;list-style:circle}
.post-labels{margin:22px 0 8px;display:flex;gap:8px;flex-wrap:wrap}
.share{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0;align-items:center}
.share b{font-size:14px;color:var(--head)}
.share a{font-size:13px;font-weight:700;padding:6px 14px;background:var(--soft);color:var(--link)}
.share a:hover{background:var(--navy);color:#fff}
.author-box{display:flex;gap:14px;align-items:center;background:var(--soft);padding:14px 16px;margin:18px 0}
.author-box .av{width:48px;height:48px;border-radius:50%;background:var(--navy);color:#fff;font-weight:700;font-size:20px;display:flex;align-items:center;justify-content:center;flex:0 0 48px}
.author-box p{margin:0;font-size:13.5px;color:var(--muted)}
.post-nav{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:20px}
.post-nav a{display:block;border:1px solid var(--line);padding:10px 14px;font-size:14px;font-weight:700}
.post-nav a small{display:block;color:var(--muted);font-weight:400}
.post-nav .nx{text-align:right}
.rel-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px 32px}
.comments{margin-top:28px;padding-top:18px;border-top:2px solid var(--line)}
.comments h3{font-size:19px}
.cmt{padding:12px 0;border-bottom:1px solid var(--line)}
.cmt b{color:var(--head)}
.cmt small{color:var(--muted);margin-left:8px}
.cmt p{margin:4px 0 0;white-space:pre-line}
.notice{padding:44px 24px;text-align:center;background:var(--soft)}
.side-h{font-size:21px;font-weight:700;margin:0 0 16px}
.sidebar .side-block{margin-bottom:28px}
.sidebar .widget{margin-bottom:26px}
.sidebar .widget h2,.sidebar .widget h3{font-size:21px;margin-bottom:14px}
.sidebar .row{gap:16px;margin-bottom:17px}
.sidebar .row-img{flex-basis:104px;height:72px}
.sidebar .row-t{font-size:16px}

/* ---------- 6) Footer ---------- */
.site-footer{background:var(--navy-dark);color:#c4d3ea}
.foot-grid{display:grid;grid-template-columns:1.9fr 1fr 1.15fr 1.2fr;gap:30px;padding:44px 0 26px}
.site-footer h4{color:#fff;font-size:20px;font-weight:700;margin-bottom:16px}
.site-footer a{color:#c4d3ea}
.site-footer a:hover{color:var(--accent)}
.foot-logo{display:flex;align-items:center;gap:7px;margin-bottom:14px}
.foot-name{font-size:30px;font-weight:900;color:#fff;text-transform:uppercase;line-height:1;letter-spacing:.4px}
.foot-about p{font-size:14.5px;line-height:1.5;margin:0 0 14px}
.foot-about .ptag{font-size:15px}
.site-footer ul{list-style:none;margin:0;padding:0}
.site-footer li{padding:5px 0;font-size:16px}
.ext::after{content:' \2197';font-size:.85em;opacity:.7}
.socials{display:flex;gap:14px;flex-wrap:wrap}
.soc{width:30px;height:30px;color:#c4d3ea;display:flex}
.soc svg{width:100%;height:100%;fill:currentColor}
.soc:hover{color:var(--accent)}
.foot-badges{margin-top:6px}
.foot-badges img{max-height:80px;margin:6px 10px 0 0}
.foot-line{border-top:2px solid rgba(255,255,255,.25);padding:22px 0;display:flex;gap:36px;align-items:center;flex-wrap:wrap;font-size:15px}
.foot-line .widget{margin:0}
.foot-line .safe{text-decoration:underline}
.foot-copy{font-size:14.5px;margin:0}
.foot-bottom .widget{display:inline}
.foot-bottom{padding:0 0 22px;font-size:12.5px;opacity:.8}
#toTop{position:fixed;right:16px;bottom:18px;width:42px;height:42px;border-radius:50%;border:0;background:var(--accent);color:#1b1b1b;font-size:20px;font-weight:700;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,.3);display:none;z-index:70}
#toTop.show{display:block}

/* ---------- v5 ADDITIONS: motion, slider, ads, mobile ---------- */
@keyframes fadeUp{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
@keyframes shimmer{to{background-position:-200% 0}}
@keyframes hbar{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes tick{to{transform:translateX(-50%)}}
body{animation:fadeUp .5s ease both}
.site-header{transition:transform .35s ease,box-shadow .3s}
.site-header.stuck{box-shadow:0 4px 18px rgba(0,0,0,.25)}
.site-header.hide{transform:translateY(-100%)}
.menu li a{position:relative}
.menu li:not(:last-child) a:after{content:'';position:absolute;left:14px;right:14px;bottom:3px;height:2px;background:var(--accent);transform:scaleX(0);transform-origin:left;transition:transform .3s}
.menu li:not(:last-child) a:hover:after{transform:scaleX(1)}
.row-t{background:linear-gradient(var(--red),var(--red)) 0 100%/0 2px no-repeat;transition:background-size .35s,color .2s}
.row-t:hover{background-size:100% 2px}
.row-img img,.bl-img img,.feat-img img{transition:transform .45s}
.row:hover .row-img img,.bl-img:hover img{transform:scale(1.07)}
.pcard{transition:transform .3s,box-shadow .3s}
.pcard:hover{transform:translateY(-4px)}
.btn,.btn-o,.tag{transition:background .25s,color .25s,transform .2s}
.btn:active{transform:scale(.97)}

/* Reveal on scroll (only when JS is on) */
.js .rv{opacity:0;transform:translateY(26px);transition:opacity .7s ease,transform .7s ease}
.js .rv.in{opacity:1;transform:none}

/* Trending ticker */
.ticker{display:flex;align-items:center;gap:12px;margin:14px 0 0;background:var(--soft);border-radius:999px;overflow:hidden;font-size:14px}
.ticker[hidden]{display:none}
.tk-l{flex:0 0 auto;background:var(--red);color:#fff;font-weight:700;font-size:12.5px;text-transform:uppercase;letter-spacing:.5px;padding:7px 16px}
.tk-w{flex:1;overflow:hidden;white-space:nowrap;min-width:0}
.tk-t{display:inline-flex;animation:tick 38s linear infinite}
.tk-w:hover .tk-t{animation-play-state:paused}
.tk-t a{color:var(--head);padding:0 22px;position:relative}
.tk-t a:after{content:'\2022';position:absolute;right:-3px;color:var(--accent)}
.tk-t a:hover{color:var(--red)}

/* Hero slider */
.hero{position:relative;overflow:hidden;border-radius:10px;background:var(--navy-dark);direction:ltr;touch-action:pan-y;box-shadow:0 10px 30px rgba(15,56,112,.18)}
.hero-track{display:flex;transition:transform .7s cubic-bezier(.65,0,.35,1);will-change:transform}
.slide{flex:0 0 100%;position:relative;display:block;aspect-ratio:16/8;min-height:250px;color:#fff;overflow:hidden}
.slide img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transform:scale(1.1);transition:transform 7s ease-out}
.slide.on img{transform:scale(1)}
.slide:after{content:'';position:absolute;inset:0;background:linear-gradient(to top,rgba(6,20,45,.92),rgba(6,20,45,.15) 65%)}
.slide-cap{position:absolute;left:0;right:0;bottom:0;padding:24px 30px 46px;z-index:2;display:flex;flex-direction:column;gap:10px;align-items:flex-start}
.slide-cap h3{color:#fff;font-size:28px;line-height:1.28;margin:0;max-width:740px;opacity:0;transform:translateY(18px);transition:opacity .7s .25s,transform .7s .25s}
.slide-cap .tag,.slide-cap .sm{opacity:0;transform:translateY(12px);transition:opacity .6s .1s,transform .6s .1s}
.slide.on .slide-cap h3,.slide.on .slide-cap .tag,.slide.on .slide-cap .sm{opacity:1;transform:none}
.slide-cap .sm{font-size:13px;color:#cfdcf1;transition-delay:.4s}
.hero-nav{position:absolute;top:50%;transform:translateY(-50%);z-index:5;width:42px;height:42px;border-radius:50%;border:0;background:rgba(255,255,255,.9);color:var(--navy);font-size:26px;line-height:1;cursor:pointer;opacity:0;transition:opacity .25s,background .25s}
.hero:hover .hero-nav,.hero-nav:focus-visible{opacity:1}
.hero-nav:hover{background:var(--accent)}
.hn-p{left:12px}.hn-n{right:12px}
.hero-dots{position:absolute;right:20px;bottom:16px;z-index:5;display:flex;gap:7px}
.hero-dots button{width:9px;height:9px;border-radius:99px;border:0;background:rgba(255,255,255,.5);cursor:pointer;padding:0;transition:width .3s,background .3s}
.hero-dots button.on{width:26px;background:var(--accent)}
.hero-bar{position:absolute;left:0;right:0;bottom:0;height:3px;z-index:5;background:rgba(255,255,255,.15)}
.hero-bar i{display:block;height:100%;background:var(--accent);transform-origin:left;transform:scaleX(0)}
.hero-bar i.run{animation:hbar 5.5s linear forwards}
.hero.paused .hero-bar i{animation-play-state:paused}
.hero-sk{aspect-ratio:16/8;min-height:250px;border-radius:10px;background:linear-gradient(90deg,var(--soft) 25%,var(--line) 50%,var(--soft) 75%);background-size:200% 100%;animation:shimmer 1.4s infinite}

/* Ad slots (Google AdSense / Ad Manager) */
.adwrap{margin:24px 0;text-align:center;max-width:100%;overflow:hidden}
.adwrap:before{content:'Advertisement';display:block;font-size:11px;letter-spacing:1.2px;text-transform:uppercase;color:var(--muted);margin-bottom:6px}
.adwrap .widget,.adwrap .section{margin:0 auto;max-width:100%}
.adwrap ins,.adwrap iframe{max-width:100%}
.adwrap.lb .widget{min-height:90px}
.adwrap.rect .widget{min-height:250px}
.adwrap.fluid .widget{min-height:120px}
.sticky-ad{position:sticky;top:86px}
.anchor{display:none}

/* Mobile bottom bar */
.bnav{display:none}
.lb-ov{position:fixed;inset:0;background:rgba(5,15,35,.92);z-index:200;display:flex;align-items:center;justify-content:center;padding:16px;cursor:zoom-out;animation:fadeUp .25s ease}
.lb-ov img{max-width:100%;max-height:100%;border-radius:6px}

/* ---------- Responsive ---------- */
/* SIDEBAR SWITCH: to show the sidebar on the home page too, replace the
   first .layout rule above with:
   .layout{grid-template-columns:minmax(0,1fr) 324px}
   and the .sidebar rule with: .sidebar{display:block}              */
@media (max-width:960px){
  .page-item .layout,.page-static_page .layout{grid-template-columns:minmax(0,1fr);gap:10px}
  .foot-grid{grid-template-columns:1fr 1fr}
}
@media (max-width:860px){
  .menu-btn{display:flex;margin-left:auto}
  .nav{display:none;order:9;width:100%;flex:0 0 100%;padding-bottom:12px}
  .nav-open .nav{display:block}
  .menu ul{flex-direction:column;align-items:stretch}
  .menu li:last-child a{display:inline-block;margin:6px 0 0}
}
@media (max-width:680px){
  .feat,.bl,.two-col,.cards{grid-template-columns:minmax(0,1fr)}
  .feat-body h3{font-size:23px}
  .bl,.two-col{gap:26px}
  .rel-grid{grid-template-columns:1fr}
  .post-full h1.post-title{font-size:25px}
  .post-nav{grid-template-columns:1fr}
  .foot-grid{grid-template-columns:1fr}
  .logo-text{font-size:26px}
  .sec-h,.lbl-head h3{font-size:21px}
  .slide{aspect-ratio:4/3;min-height:230px}
  .slide-cap{padding:16px 16px 40px}
  .slide-cap h3{font-size:19px}
  .hero-nav{display:none}
  .hero-dots{right:12px;bottom:12px}
  .hero-sk{aspect-ratio:4/3}
  .ticker{margin-top:10px;font-size:13px}
  .row-img{flex-basis:96px;height:68px}
  .row{gap:14px}
  .pcard h2{font-size:18px}
  .adwrap.lb .widget{min-height:100px}
  body{padding-bottom:62px}
  #toTop{display:none!important}
  .bnav{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:90;background:var(--navy);padding:6px 6px calc(6px + env(safe-area-inset-bottom));box-shadow:0 -4px 16px rgba(0,0,0,.25)}
  .bnav a,.bnav button{flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;background:transparent;border:0;color:#fff;font:500 11px var(--font);padding:5px 0;cursor:pointer}
  .bnav svg{width:22px;height:22px;fill:currentColor}
  .bnav a:active,.bnav button:active{color:var(--accent)}
  .anchor{display:block;position:fixed;left:0;right:0;bottom:56px;z-index:80;background:var(--bg);border-top:1px solid var(--line);text-align:center;max-height:100px;overflow:hidden;padding-top:2px}
  .anchor.off{display:none}
  .anchor-x{position:absolute;right:4px;top:-1px;z-index:2;border:0;background:var(--soft);color:var(--head);width:24px;height:22px;font-size:16px;line-height:1;cursor:pointer}
  .anchor .ad{margin:0}
}
@media (max-width:420px){
  .wrap{padding:0 12px}
  .post-body{font-size:16px;line-height:1.8}
  .menu li a{padding:10px 8px}
}
@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important;scroll-behavior:auto!important}.js .rv{opacity:1;transform:none}}

/* =========================================================
   v6 MOTION PACK - Pro scrolling nav + post body animations
   (all new rules; safe to delete this whole block to undo)
   ========================================================= */
@keyframes navFlow{to{background-position:-200% 0}}
@keyframes navDrop{from{opacity:0;transform:translateY(-14px)}to{opacity:1;transform:none}}
@keyframes navShine{0%,70%{transform:translateX(-130%) skewX(-20deg)}100%{transform:translateX(330%) skewX(-20deg)}}
@keyframes pmTitle{from{opacity:0;transform:translateY(20px);clip-path:inset(0 0 100% 0)}to{opacity:1;transform:none;clip-path:inset(0 0 0 0)}}
@keyframes pmFade{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
@keyframes lbZoom{from{opacity:0;transform:scale(.92)}to{opacity:1;transform:none}}

/* ---------- NAV: header ---------- */
.site-header{transition:transform .35s ease,box-shadow .3s,background .3s,backdrop-filter .3s}
.site-header.stuck{background:rgba(15,56,112,.94);-webkit-backdrop-filter:saturate(160%) blur(10px);backdrop-filter:saturate(160%) blur(10px)}
.site-header:after{content:'';position:absolute;left:0;right:0;bottom:0;height:2px;pointer-events:none;background:linear-gradient(90deg,transparent,var(--accent),#fff,var(--accent),transparent);background-size:200% 100%;animation:navFlow 3.5s linear infinite;opacity:0;transition:opacity .4s}
.site-header.stuck:after{opacity:1}
.bar{transition:min-height .3s ease}
.site-header.stuck .bar{min-height:54px}
.logo-text{transition:font-size .3s ease}
.site-header.stuck .logo-text{font-size:25px}
.logo svg{transition:transform .7s cubic-bezier(.3,1.4,.5,1)}
.logo:hover svg{transform:rotate(360deg) scale(1.12)}

/* progress bar with glowing head */
#progress{background:linear-gradient(90deg,var(--red),var(--accent));box-shadow:0 0 10px rgba(255,193,7,.7);transition:width .12s linear}
#progress:after{content:'';position:absolute;right:-2px;top:-3px;width:9px;height:9px;border-radius:50%;background:#fff;box-shadow:0 0 12px 3px var(--accent);opacity:.95}

/* menu: staggered entrance + sliding pill indicator */
.menu ul{position:relative}
.menu li{animation:navDrop .6s cubic-bezier(.2,.8,.2,1) both;animation-delay:calc(var(--i,0)*70ms + .12s)}
.nav-ind{position:absolute;left:0;top:0;height:0;width:0;border-radius:999px;background:rgba(255,255,255,.12);box-shadow:inset 0 -2px 0 var(--accent);opacity:0;pointer-events:none;transition:transform .38s cubic-bezier(.3,1.2,.4,1),width .38s cubic-bezier(.3,1.2,.4,1),height .3s,opacity .25s}
.nav-ind.on{opacity:1}
.has-ind .menu li:not(:last-child) a:after{display:none}
.menu li a{position:relative;z-index:1;transition:color .25s}
.menu li a.cur{color:var(--accent)}
.menu li:last-child a{position:relative;overflow:hidden}
.menu li:last-child a:after{content:'';position:absolute;top:0;bottom:0;left:0;width:38%;background:linear-gradient(90deg,transparent,rgba(255,255,255,.65),transparent);animation:navShine 4.5s ease-in-out infinite;pointer-events:none}

/* reading-percent chip (posts only) */
.rd-pct{display:none;align-items:center;font-size:12px;font-weight:700;color:#1b1b1b;background:var(--accent);padding:3px 9px;border-radius:999px;opacity:0;transform:scale(.7);transition:opacity .25s,transform .3s cubic-bezier(.3,1.4,.5,1);min-width:44px;justify-content:center;font-variant-numeric:tabular-nums}
.page-item .rd-pct{display:inline-flex}
.rd-pct.on{opacity:1;transform:none}

/* mobile menu: slide-down + stagger */
@media (max-width:860px){
  .nav-ind,.rd-pct{display:none!important}
  .nav-open .nav{animation:navDrop .35s ease both}
  .menu li{animation-delay:calc(var(--i,0)*55ms + .05s)}
}

/* back-to-top: circular reading ring */
#toTop{background:conic-gradient(var(--navy) var(--p,0%),var(--accent) 0);transition:transform .25s}
#toTop:before{content:'';position:absolute;inset:3px;border-radius:50%;background:var(--accent);z-index:-1}
#toTop:hover{transform:translateY(-3px)}

/* ---------- POST BODY: motion ---------- */
.page-item .post-full .post-title{animation:pmTitle .9s cubic-bezier(.2,.8,.2,1) both}
.page-item .post-full .meta2{animation:pmFade .8s .35s ease both}

.pm{opacity:0;transform:translateY(24px);transition:opacity .75s cubic-bezier(.2,.7,.2,1) var(--d,0s),transform .75s cubic-bezier(.2,.7,.2,1) var(--d,0s),filter .75s var(--d,0s),clip-path .9s cubic-bezier(.2,.7,.2,1) var(--d,0s)}
.pm.in{opacity:1;transform:none}
.pm-img{transform:scale(.94);filter:blur(10px)}
.pm-img.in{filter:none}
.pm-q{transform:none;clip-path:inset(0 100% 0 0)}
.pm-q.in{clip-path:inset(0 0 0 0)}
.pm-c{transform:translateY(34px) scale(.98)}
.pm-h{transform:translateX(-22px)}

.post-body h2{position:relative;padding-bottom:.35em}
.post-body h2:after{content:'';position:absolute;left:0;bottom:0;height:3px;width:64px;border-radius:2px;background:linear-gradient(90deg,var(--accent),var(--red));transform:scaleX(0);transform-origin:left;transition:transform .9s cubic-bezier(.2,.7,.2,1) .3s}
.post-body h2.in:after{transform:scaleX(1)}
.post-body h3{border-left:0 solid var(--accent);transition:border-left-width .5s .25s,padding-left .5s .25s,opacity .75s var(--d,0s),transform .75s var(--d,0s)}
.post-body h3.in{border-left-width:4px;padding-left:10px}

.post-body p a,.post-body li a{background:linear-gradient(var(--red),var(--red)) 0 100%/0 2px no-repeat;transition:background-size .35s,color .2s}
.post-body p a:hover,.post-body li a:hover{background-size:100% 2px}

.pm-l li{opacity:0;transform:translateX(-16px);transition:opacity .5s,transform .5s;transition-delay:calc(var(--i,0)*70ms + .15s)}
.pm-l.in li{opacity:1;transform:none}

.post-body img{transition:transform .5s cubic-bezier(.2,.7,.2,1),box-shadow .5s,opacity .75s var(--d,0s),filter .75s var(--d,0s)}
.post-body img:hover{transform:scale(1.015);box-shadow:0 12px 30px rgba(10,42,85,.28)}
.post-body blockquote{box-shadow:inset 0 0 0 0 rgba(255,193,7,.0);transition:box-shadow .4s,opacity .75s var(--d,0s),transform .75s var(--d,0s),clip-path .9s var(--d,0s)}

.pre-w{position:relative}
.pre-w pre{margin:0}
.cp-btn{position:absolute;top:8px;right:8px;z-index:2;border:0;border-radius:4px;background:rgba(255,255,255,.14);color:#e6eefb;font:600 12px var(--font);padding:4px 10px;cursor:pointer;opacity:0;transform:translateY(-4px);transition:opacity .25s,transform .25s,background .25s}
.pre-w:hover .cp-btn,.cp-btn:focus-visible{opacity:1;transform:none}
.cp-btn:hover{background:var(--accent);color:#1b1b1b}
@media (hover:none){.cp-btn{opacity:1;transform:none}}

/* TOC scrollspy */
.toc li{transition:transform .3s,color .3s}
.toc li a{transition:color .25s}
.toc li.act{transform:translateX(5px);list-style:disc}
.toc li.act>a{color:var(--red);font-weight:700}

.lb-ov img{animation:lbZoom .35s cubic-bezier(.2,.8,.2,1)}

@media (prefers-reduced-motion:reduce){
  .pm,.pm-l li{opacity:1!important;transform:none!important;filter:none!important;clip-path:none!important}
  .site-header:after,.menu li:last-child a:after{display:none}
}

body.script:
//
(function(){
  function $(s,c){return (c||document).querySelector(s)}
  function $$(s,c){return Array.prototype.slice.call((c||document).querySelectorAll(s))}
  function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
  function big(u,w,h){return u?u.replace(/\/(?:s\d+|w\d+-h\d+)[-\w]*\//,'/w'+w+'-h'+h+'-p-k-no-nu/'):''}
  function fdate(s){try{return new Date(s).toLocaleDateString('en-US',{year:'numeric',month:'long',day:'2-digit'})}catch(e){return ''}}
  function lurl(l){return '/search/label/'+encodeURIComponent(l)+'?max-results=12'}
  var B=document.body;

  /* ---------- UI basics ---------- */
  var mb=$('#menuBtn');if(mb){mb.addEventListener('click',function(){B.classList.toggle('nav-open')})}
  var sb=$('#searchBtn');
  if(sb){sb.addEventListener('click',function(){B.classList.toggle('search-open');if(B.classList.contains('search-open')){var i=$('.search-pop input');if(i){i.focus()}}})}

  /* Logo: first 2 letters yellow */
  $$('.logo-text a').forEach(function(a){
    var t=a.textContent.trim();
    if(t.length>3){a.innerHTML='<span class="go">'+esc(t.slice(0,2))+'</span>'+esc(t.slice(2))}
  });
  var fn=$('.foot-name');
  if(fn){var ft0=fn.textContent.trim();if(ft0.length>3){fn.innerHTML='<span class="go">'+esc(ft0.slice(0,2))+'</span>'+esc(ft0.slice(2))}}

  /* Copyright years */
  var cy=$('.cy');
  if(cy){var now=new Date().getFullYear(),from=parseInt(cy.getAttribute('data-from'),10)||now;cy.textContent=from<now?from+' - '+now:String(now)}

  /* Dark mode */
  var tb=$('#themeBtn');
  if(tb){
    tb.addEventListener('click',function(){
      var d=document.documentElement.getAttribute('data-theme')==='dark';
      if(d){document.documentElement.removeAttribute('data-theme')}else{document.documentElement.setAttribute('data-theme','dark')}
      try{localStorage.setItem('theme',d?'light':'dark')}catch(e){}
    });
  }

  /* Progress + back to top */
  var pg=$('#progress'),tt=$('#toTop');
  function onScroll(){
    var h=document.documentElement,max=h.scrollHeight-h.clientHeight,st=h.scrollTop||B.scrollTop;
    if(pg){pg.style.width=(max>0?(st/max*100):0)+'%'}
    if(tt){tt.classList.toggle('show',st>500)}
  }
  window.addEventListener('scroll',onScroll,{passive:true});onScroll();
  if(tt){tt.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'})})}

  /* Footer: external link arrows + social icons */
  $$('.foot-col a').forEach(function(a){
    if(a.classList.contains('soc')){return}
    if(a.hostname&&a.hostname!==location.hostname){a.target='_blank';a.rel='noopener';a.classList.add('ext')}
  });
  var ICONS={
    facebook:'M24 12a12 12 0 1 0-13.9 11.9v-8.4H7.1V12h3V9.4c0-3 1.8-4.7 4.5-4.7 1.3 0 2.7.2 2.7.2v3h-1.5c-1.5 0-2 .9-2 1.9V12h3.4l-.5 3.5h-2.9v8.4A12 12 0 0 0 24 12z',
    linkedin:'M20.45 20.45h-3.55v-5.57c0-1.33-.03-3.04-1.85-3.04-1.85 0-2.14 1.45-2.14 2.94v5.67H9.35V9h3.41v1.56h.05c.48-.9 1.64-1.85 3.37-1.85 3.6 0 4.27 2.37 4.27 5.46v6.28zM5.34 7.43a2.06 2.06 0 1 1 0-4.12 2.06 2.06 0 0 1 0 4.12zM7.12 20.45H3.56V9h3.56v11.45zM22.23 0H1.77C.79 0 0 .77 0 1.73v20.54C0 23.23.79 24 1.77 24h20.46c.98 0 1.77-.77 1.77-1.73V1.73C24 .77 23.21 0 22.23 0z',
    bluesky:'M12 10.8c-1.09-2.11-4.05-6.05-6.8-8C2.57.94 1.56 1.27.9 1.57.14 1.91 0 3.08 0 3.77c0 .69.38 5.65.62 6.48.82 2.74 3.71 3.66 6.38 3.36-3.91.58-7.39 2.01-2.83 7.08 5.01 5.19 6.87-1.11 7.82-4.31.95 3.2 2.05 9.27 7.73 4.31 4.27-4.31 1.17-6.5-2.74-7.08 2.67.3 5.57-.62 6.38-3.36.25-.83.62-5.79.62-6.48 0-.69-.14-1.86-.9-2.2-.66-.3-1.66-.62-4.3 1.24C16.05 4.75 13.09 8.69 12 10.8z',
    rss:'M19.2 24C19.2 13.47 10.53 4.8 0 4.8V0c13.17 0 24 10.84 24 24h-4.8zM3.29 17.42c1.81 0 3.29 1.48 3.29 3.3 0 1.81-1.49 3.28-3.3 3.28C1.47 24 0 22.53 0 20.71s1.48-3.29 3.29-3.29zM15.91 24h-4.67c0-6.17-5.07-11.25-11.24-11.25V8.09c8.73 0 15.91 7.18 15.91 15.91z'
  };
  $$('.soc').forEach(function(a){
    var n=(a.getAttribute('data-n')||'').toLowerCase().replace(/[^a-z]/g,''),p=ICONS[n];
    var svg=p?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+p+'"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="11"/></svg>';
    a.insertAdjacentHTML('afterbegin',svg);
  });

  function fixThumbs(root){$$('img.js-thumb',root).forEach(function(i){i.src=big(i.getAttribute('src'),640,360);i.classList.remove('js-thumb')})}
  fixThumbs();

  /* ---------- Feed helpers ---------- */
  function parse(e){
    var link='';
    (e.link||[]).forEach(function(l){if(l.rel==='alternate'){link=l.href}});
    var html=(e.content&&e.content.$t)||(e.summary&&e.summary.$t)||'';
    return {
      title:e.title.$t,url:link,
      img:e['media$thumbnail']?e['media$thumbnail'].url:'',
      date:e.published.$t,
      text:html.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim(),
      cat:(e.category&&e.category[0])?e.category[0].term:''
    };
  }
  function feed(label,max,cb){
    var u='/feeds/posts/default'+(label?'/-/'+encodeURIComponent(label):'')+'?alt=json&max-results='+max;
    fetch(u).then(function(r){return r.json()}).then(function(d){
      cb(((d.feed&&d.feed.entry)||[]).map(parse));
      setTimeout(reveal,30);
    }).catch(function(){cb([])});
  }
  function pic(p,w,h){return p.img?'<img loading="lazy" alt="'+esc(p.title)+'" src="'+esc(big(p.img,w,h))+'"/>':''}
  function tag(c){return c?'<a class="tag" href="'+lurl(c)+'">'+esc(c)+'</a>':''}
  function row(p){
    return '<li class="row"><a class="row-img" href="'+esc(p.url)+'">'+pic(p,230,160)+'</a>'+
      '<a class="row-t" href="'+esc(p.url)+'">'+esc(p.title)+'</a></li>';
  }
  function rows(a,cls){return '<ul class="rows'+(cls?' '+cls:'')+'">'+a.map(row).join('')+'</ul>'}

  /* ---------- 2) Selected Articles ---------- */
  var ft=$('#featured');
  if(ft){
    var RM=window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches;
    function buildHero(a){
      var n=a.length;
      ft.innerHTML='<div class="hero" role="region" aria-roledescription="carousel" aria-label="Selected articles"><div class="hero-track">'+
        a.map(function(p,i){
          return '<a class="slide'+(i?'':' on')+'" href="'+esc(p.url)+'" aria-label="'+(i+1)+' / '+n+'">'+pic(p,1000,500)+
            '<span class="slide-cap">'+(p.cat?'<span class="tag">'+esc(p.cat)+'</span>':'')+
            '<h3>'+esc(p.title)+'</h3><span class="sm">'+fdate(p.date)+'</span></span></a>';
        }).join('')+'</div>'+
        (n>1?'<button class="hero-nav hn-p" type="button" aria-label="Previous">&#8249;</button><button class="hero-nav hn-n" type="button" aria-label="Next">&#8250;</button>'+
        '<div class="hero-dots">'+a.map(function(p,i){return '<button type="button" aria-label="Slide '+(i+1)+'"'+(i?'':' class="on"')+'></button>'}).join('')+'</div>'+
        '<div class="hero-bar"><i></i></div>':'')+'</div>';
      var hero=$('.hero',ft);if(!hero||n<2){return}
      var track=$('.hero-track',hero),slides=$$('.slide',hero),dots=$$('.hero-dots button',hero),bar=$('.hero-bar i',hero),idx=0,timer=null,drag=false,sx=0,sy=0;
      function go(i){
        idx=(i+n)%n;
        track.style.transform='translateX(-'+(idx*100)+'%)';
        slides.forEach(function(s,k){s.classList.toggle('on',k===idx)});
        dots.forEach(function(d,k){d.classList.toggle('on',k===idx)});
        if(bar){bar.classList.remove('run');void bar.offsetWidth;if(!RM&&!hero.classList.contains('paused')){bar.classList.add('run')}}
        play();
      }
      function play(){clearTimeout(timer);if(RM||hero.classList.contains('paused')){return}timer=setTimeout(function(){go(idx+1)},5500)}
      function pause(){hero.classList.add('paused');clearTimeout(timer)}
      function resume(){hero.classList.remove('paused');go(idx)}
      $('.hn-p',hero).addEventListener('click',function(){go(idx-1)});
      $('.hn-n',hero).addEventListener('click',function(){go(idx+1)});
      dots.forEach(function(d,k){d.addEventListener('click',function(){go(k)})});
      hero.addEventListener('mouseenter',pause);hero.addEventListener('mouseleave',resume);
      hero.addEventListener('focusin',pause);hero.addEventListener('focusout',resume);
      hero.addEventListener('keydown',function(e){if(e.key==='ArrowLeft'){go(idx-1)}else if(e.key==='ArrowRight'){go(idx+1)}});
      hero.addEventListener('touchstart',function(e){var t=e.touches[0];sx=t.clientX;sy=t.clientY;drag=false;pause()},{passive:true});
      hero.addEventListener('touchend',function(e){
        var t=e.changedTouches[0],dx=t.clientX-sx,dy=t.clientY-sy;
        if(Math.abs(dx)>40&&Math.abs(dx)>Math.abs(dy)){drag=true;go(dx<0?idx+1:idx-1)}
        setTimeout(function(){drag=false},50);resume();
      },{passive:true});
      hero.addEventListener('click',function(e){if(drag){e.preventDefault()}},true);
      document.addEventListener('visibilitychange',function(){if(document.hidden){pause()}else{resume()}});
      go(0);
    }
    var fmax=parseInt(ft.getAttribute('data-max'),10)||5;
    feed(ft.getAttribute('data-label'),fmax,function(a){
      if(a.length){buildHero(a)}
      else{feed('',fmax,function(b){if(b.length){buildHero(b)}else{ft.parentNode.style.display='none'}})}
    });
  }

  /* ---------- Trending ticker ---------- */
  var tk=$('#ticker');
  if(tk){
    feed('',8,function(a){
      if(!a.length){return}
      var items=a.map(function(p){return '<a href="'+esc(p.url)+'">'+esc(p.title)+'</a>'}).join('');
      tk.innerHTML='<span class="tk-l">Trending</span><div class="tk-w"><div class="tk-t"><span>'+items+'</span><span aria-hidden="true">'+items+'</span></div></div>';
      tk.removeAttribute('hidden');
    });
  }

  /* ---------- 3) Label block: tab + big + 3 rows ---------- */
  $$('.tabsec').forEach(function(el){
    var l=el.getAttribute('data-label');
    feed(l,4,function(a){
      if(!a.length){el.style.display='none';return}
      var b=a[0];
      el.innerHTML='<div class="tab-head"><a class="tab" href="'+lurl(l)+'">'+esc(el.getAttribute('data-title')||l)+'</a></div>'+
        '<div class="bl"><div><a class="bl-img" href="'+esc(b.url)+'">'+pic(b,640,360)+'</a>'+
        '<h3 class="t1"><a href="'+esc(b.url)+'">'+esc(b.title)+'</a></h3></div>'+
        rows(a.slice(1,4))+'</div>';
    });
  });

  /* ---------- 4) Two label lists ---------- */
  $$('.lbl').forEach(function(el){
    var l=el.getAttribute('data-label'),m=el.getAttribute('data-max')||5;
    feed(l,m,function(a){
      if(!a.length){el.style.display='none';return}
      el.innerHTML='<div class="lbl-head"><h3>'+esc(el.getAttribute('data-title')||l)+'</h3><span class="stars">\u2605\u2605\u2605</span>'+
        '<a class="btn-o" href="'+lurl(l)+'">See all \u00bb</a></div>'+rows(a);
    });
  });

  /* ---------- Sidebar block (only when the sidebar is visible) ---------- */
  $$('.side-block').forEach(function(el){
    if(!el.offsetParent){return}
    var l=el.getAttribute('data-label'),m=el.getAttribute('data-max')||5;
    function paint(a){el.innerHTML='<h3 class="side-h">'+esc(el.getAttribute('data-title')||l)+'</h3>'+rows(a)}
    feed(l,m,function(a){
      if(a.length){paint(a)}
      else{feed('',m,function(b){if(b.length){paint(b)}else{el.style.display='none'}})}
    });
  });

  /* ---------- 5) AJAX Load More ---------- */
  var more=$('#loadMore'),pgrid=$('#postGrid');
  if(more&&pgrid){
    more.addEventListener('click',function(e){
      e.preventDefault();
      var txt=more.textContent;more.textContent='Loading...';
      fetch(more.getAttribute('href')).then(function(r){return r.text()}).then(function(t){
        var doc=new DOMParser().parseFromString(t,'text/html');
        var g=doc.querySelector('#postGrid');
        if(g){$$('.pcard',g).forEach(function(c){pgrid.appendChild(document.importNode(c,true))})}
        fixThumbs(pgrid);
        var nm=doc.querySelector('#loadMore');
        if(nm){more.setAttribute('href',nm.getAttribute('href'));more.textContent=txt}
        else{more.parentNode.removeChild(more)}
      }).catch(function(){window.location=more.getAttribute('href')});
    });
  }

  /* ---------- Single post extras ---------- */
  var body=$('#postBody');
  if(body&&B.classList.contains('page-item')){
    var words=(body.textContent||'').trim().split(/\s+/).length,rt=$('#rt');
    if(rt){rt.textContent=Math.max(1,Math.round(words/200))+' min read'}

    var hs=$$('h2,h3',body);
    if(hs.length>=3){
      var det=document.createElement('details');det.className='toc';det.open=true;
      var html='<summary>Table of Contents</summary><ol>';
      hs.forEach(function(h,i){
        if(!h.id){h.id='sec-'+(i+1)}
        html+='<li'+(h.tagName==='H3'?' class="sub"':'')+'><a href="#'+h.id+'">'+esc(h.textContent)+'</a></li>';
      });
      det.innerHTML=html+'</ol>';
      body.insertBefore(det,body.firstChild);
    }

    var sh=$('#share');
    if(sh){
      var u=encodeURIComponent(location.href),t=encodeURIComponent(document.title);
      var map={fb:'https://www.facebook.com/sharer/sharer.php?u='+u,x:'https://twitter.com/intent/tweet?url='+u+'&text='+t,wa:'https://wa.me/?text='+t+'%20'+u,tg:'https://t.me/share/url?url='+u+'&text='+t};
      $$('a',sh).forEach(function(a){
        var n=a.getAttribute('data-net');
        if(map[n]){a.href=map[n]}
        else{a.addEventListener('click',function(e){e.preventDefault();if(navigator.clipboard){navigator.clipboard.writeText(location.href);a.textContent='Copied!'}})}
      });
    }

    var av=$('.author-box .av');
    if(av){av.textContent=(av.getAttribute('data-name')||'?').trim().charAt(0).toUpperCase()}

    var rel=$('#related'),first=$('.post-labels a');
    if(rel&&first){
      feed(first.textContent.trim(),7,function(a){
        var cur=location.href.split('?')[0].split('#')[0];
        a=a.filter(function(p){return p.url!==cur}).slice(0,4);
        if(a.length){rel.innerHTML='<h2 class="sec-h" style="margin-top:30px">Related Articles</h2>'+rows(a,'rel-grid')}
      });
    }

    var cm=$('#comments');
    if(cm){
      var id=cm.getAttribute('data-post'),list=$('#comment-list');
      fetch('/feeds/'+id+'/comments/default?alt=json&max-results=100').then(function(r){return r.json()}).then(function(d){
        var es=(d.feed&&d.feed.entry)||[];
        if(!es.length){list.innerHTML='<p class="meta2">No comments yet. Be the first to comment.</p>';return}
        list.innerHTML=es.map(function(e){
          var txt=((e.content&&e.content.$t)||'').replace(/<br\s*\/?>/gi,'\n').replace(/<[^>]*>/g,'');
          var nm=(e.author&&e.author[0]&&e.author[0].name&&e.author[0].name.$t)||'Anonymous';
          return '<div class="cmt"><b>'+esc(nm)+'</b><small>'+fdate(e.published.$t)+'</small><p>'+esc(txt)+'</p></div>';
        }).join('');
      }).catch(function(){list.innerHTML=''});
    }

    /* In-article ad: move after the 3rd content block */
    var src=$('#inArtSrc');
    if(src){
      var kids=Array.prototype.filter.call(body.children,function(c){return !c.classList.contains('toc')});
      if(src.querySelector('.widget')&&kids.length>=3){kids[2].parentNode.insertBefore(src,kids[2].nextSibling)}
    }

    /* Image lightbox */
    $$('img',body).forEach(function(im){
      if(im.closest('a[href]')&&!/\.(jpe?g|png|gif|webp)/i.test(im.closest('a').getAttribute('href')||'')){return}
      im.style.cursor='zoom-in';
      im.addEventListener('click',function(e){
        e.preventDefault();
        var a=im.closest('a'),full=(a&&a.href)||im.src.replace(/\/s\d+(-[a-z0-9]+)?\//,'/s1600/');
        var ov=document.createElement('div');ov.className='lb-ov';
        ov.innerHTML='<img alt="" src="'+esc(full)+'"/>';
        function close(){if(ov.parentNode){ov.parentNode.removeChild(ov)}document.removeEventListener('keydown',key)}
        function key(ev){if(ev.key==='Escape'){close()}}
        ov.addEventListener('click',close);document.addEventListener('keydown',key);
        document.body.appendChild(ov);
      });
    });
  }

  /* ---------- Ad slots: hide empty ones (no wasted space / labels) ---------- */
  $$('.adwrap').forEach(function(w){if(!w.querySelector('.widget')){w.style.display='none'}});
  var anc=$('#anchorAd');
  if(anc){
    if(!anc.querySelector('.widget')){anc.classList.add('off')}
    var ax=$('.anchor-x',anc);if(ax){ax.addEventListener('click',function(){anc.classList.add('off')})}
  }

  /* ---------- Mobile bottom bar ---------- */
  var bs=$('#bSearch'),bt=$('#bTheme'),bp=$('#bTop');
  if(bs){bs.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'});if(!B.classList.contains('search-open')&&sb){sb.click()}else{var i=$('.search-pop input');if(i){i.focus()}}})}
  if(bt&&tb){bt.addEventListener('click',function(){tb.click()})}
  if(bp){bp.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'})})}

  /* ---------- Header: hide on scroll down, show on scroll up ---------- */
  var hd=$('.site-header'),lastY=0;
  if(hd){
    window.addEventListener('scroll',function(){
      var y=window.pageYOffset||0;
      hd.classList.toggle('stuck',y>10);
      if(B.classList.contains('nav-open')||B.classList.contains('search-open')){hd.classList.remove('hide')}
      else if(y>240&&y>lastY+6){hd.classList.add('hide')}
      else if(y<lastY-6||y<=240){hd.classList.remove('hide')}
      lastY=y;
    },{passive:true});
  }

  /* ---------- Reveal on scroll ---------- */
  var io=('IntersectionObserver' in window)?new IntersectionObserver(function(es){
    es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}});
  },{threshold:.08,rootMargin:'0px 0px -40px 0px'}):null;
  function reveal(){
    $$('.blk,.pcard,.sec-row,.row,.post-nav,.author-box,.share,.side-block').forEach(function(el){
      if(el.getAttribute('data-rv')){return}
      el.setAttribute('data-rv','1');
      if(!io){return}
      el.classList.add('rv');io.observe(el);
    });
  }
  reveal();
})();
