(function(){
  function $(s,c){return (c||document).querySelector(s)}
  function $$(s,c){return Array.prototype.slice.call((c||document).querySelectorAll(s))}
  var B=document.body,RM=window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches;

  /* ===== NAV: sliding pill indicator + active link ===== */
  var ul=$('.menu ul');
  if(ul){
    var lis=$$('li',ul);
    lis.forEach(function(li,i){li.style.setProperty('--i',i)});
    var ind=document.createElement('span');ind.className='nav-ind';ind.setAttribute('aria-hidden','true');
    ul.appendChild(ind);B.classList.add('has-ind');

    var lab='';
    var pth=decodeURIComponent(location.pathname).toLowerCase();
    if(pth.indexOf('/search/label/')===0){lab=pth.split('/search/label/')[1].replace(/\/$/,'')}
    else{var fl=$('.post-labels a');if(fl){lab=fl.textContent.trim().toLowerCase()}}
    var active=null;
    if(lab){
      lis.forEach(function(li){
        var a=$('a',li);if(!a){return}
        var lp=decodeURIComponent(a.pathname||'').toLowerCase();
        if(lp.indexOf('/search/label/')===0&&lp.split('/search/label/')[1].replace(/\/$/,'')===lab&&li!==lis[lis.length-1]){
          a.classList.add('cur');a.setAttribute('aria-current','page');active=li;
        }
      });
    }
    function moveTo(li){
      if(!li||li===lis[lis.length-1]){ind.classList.remove('on');return}
      ind.style.width=li.offsetWidth+'px';
      ind.style.height=li.offsetHeight+'px';
      ind.style.transform='translate('+li.offsetLeft+'px,'+li.offsetTop+'px)';
      ind.classList.add('on');
    }
    function rest(){if(active){moveTo(active)}else{ind.classList.remove('on')}}
    lis.forEach(function(li){
      li.addEventListener('mouseenter',function(){moveTo(li)});
      li.addEventListener('focusin',function(){moveTo(li)});
    });
    ul.addEventListener('mouseleave',rest);
    ul.addEventListener('focusout',function(){setTimeout(function(){if(!ul.contains(document.activeElement)){rest()}},10)});
    window.addEventListener('resize',rest);
    window.addEventListener('load',rest);
    setTimeout(rest,700);
  }

  /* ===== NAV: reading-percent chip ===== */
  var body=$('#postBody'),isPost=body&&B.classList.contains('page-item');
  var chip=null;
  if(isPost){
    var sbtn=$('#searchBtn');
    if(sbtn&&sbtn.parentNode){
      chip=document.createElement('span');chip.className='rd-pct';chip.setAttribute('aria-hidden','true');chip.textContent='0%';
      sbtn.parentNode.insertBefore(chip,sbtn);
    }
  }

  /* ===== Scroll: progress bar, ring, chip, TOC scrollspy (rAF throttled) ===== */
  var pg=$('#progress'),tt=$('#toTop'),ticking=false,spyHs=[],spyLis=[];
  function frame(){
    ticking=false;
    var h=document.documentElement,max=h.scrollHeight-h.clientHeight,st=window.pageYOffset||h.scrollTop||0;
    var p=max>0?st/max:0;
    if(isPost){
      var r=body.getBoundingClientRect(),den=r.height-window.innerHeight*.6;
      p=den>1?Math.min(1,Math.max(0,-r.top/den)):(r.top<0?1:0);
    }
    p=Math.min(1,Math.max(0,p));
    if(pg){pg.style.width=(p*100)+'%'}
    if(tt){tt.style.setProperty('--p',(p*100).toFixed(1)+'%')}
    if(chip){chip.textContent=Math.round(p*100)+'%';chip.classList.toggle('on',p>.01)}
    if(spyHs.length){
      var cur=-1;
      for(var i=0;i<spyHs.length;i++){if(spyHs[i].getBoundingClientRect().top<130){cur=i}}
      spyLis.forEach(function(li,i){if(li){li.classList.toggle('act',i===cur)}});
    }
  }
  function req(){if(!ticking){ticking=true;requestAnimationFrame(frame)}}
  window.addEventListener('scroll',req,{passive:true});
  window.addEventListener('resize',req);

  /* ===== POST BODY: motion ===== */
  if(isPost){
    /* code blocks: copy button */
    $$('pre',body).forEach(function(pre){
      if(pre.parentNode.classList.contains('pre-w')){return}
      var w=document.createElement('div');w.className='pre-w';
      pre.parentNode.insertBefore(w,pre);w.appendChild(pre);
      var b=document.createElement('button');b.type='button';b.className='cp-btn';b.textContent='Copy';
      b.addEventListener('click',function(){
        var t=pre.innerText||pre.textContent||'';
        function done(){b.textContent='Copied!';setTimeout(function(){b.textContent='Copy'},1500)}
        if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(t).then(done,done)}else{done()}
      });
      w.appendChild(b);
    });

    /* TOC scrollspy hooks */
    var toc=$('.toc',body);
    if(toc){
      $$('li',toc).forEach(function(li){
        var a=$('a',li),id=a&&a.getAttribute('href');
        if(id&&id.charAt(0)==='#'){
          var h=document.getElementById(id.slice(1));
          if(h){spyHs.push(h);spyLis.push(li)}
        }
      });
    }

    /* scroll-reveal for each top-level block */
    if(!RM&&'IntersectionObserver' in window){
      var io=new IntersectionObserver(function(es){
        var k=0;
        es.forEach(function(e){
          if(e.isIntersecting){
            e.target.style.setProperty('--d',Math.min(k*.08,.32)+'s');k++;
            e.target.classList.add('in');io.unobserve(e.target);
          }
        });
      },{threshold:.06,rootMargin:'0px 0px -6% 0px'});

      Array.prototype.slice.call(body.children).forEach(function(el){
        if(el.id==='inArtSrc'||el.classList.contains('toc')||el.classList.contains('adwrap')||el.querySelector('ins.adsbygoogle,.widget')){return}
        var t=el.tagName,cls='pm';
        if(/^H[2-4]$/.test(t)){cls+=' pm-h'}
        else if(t==='BLOCKQUOTE'){cls+=' pm-q'}
        else if(t==='UL'||t==='OL'){
          cls+=' pm-l';
          $$(':scope > li',el).forEach(function(li,i){li.style.setProperty('--i',Math.min(i,10))});
        }
        else if(t==='PRE'||el.classList.contains('pre-w')){cls+=' pm-c'}
        else if(t==='IMG'||t==='FIGURE'||el.classList.contains('separator')||el.querySelector('img')){cls+=' pm-img'}
        cls.split(' ').forEach(function(c){el.classList.add(c)});
        io.observe(el);
      });
    }
  }

  req();
})();
